#!/usr/bin/env bash
# Install or update Auto Ontology for ERPNext. Generated by Frappe2Ontology.
#
#   ./setup.sh           first install, or update to AUTO_ONTOLOGY_REF in .env
#   ./setup.sh status    show containers
#   ./setup.sh logs      follow logs
#   ./setup.sh stop      stop everything (data is kept)
set -euo pipefail
cd "$(dirname "$0")"

say()  { printf '\033[1;34m==>\033[0m %s\n' "$*"; }
die()  { printf '\033[1;31mError:\033[0m %s\n' "$*" >&2; exit 1; }
envv() { grep -E "^$1=" .env | tail -1 | cut -d= -f2- ; }

[ -f .env ] || die ".env is missing. Download the server kit again from Ontology Export Settings."
command -v docker >/dev/null || die "Docker is not installed. See https://docs.docker.com/engine/install/"
docker compose version >/dev/null 2>&1 || die "Docker Compose v2 is required (docker compose ...)."
command -v git >/dev/null || die "git is not installed."

case "${1:-install}" in
  status) docker compose ps; exit 0 ;;
  logs)   docker compose logs -f --tail=100; exit 0 ;;
  stop)   docker compose stop; exit 0 ;;
  install|update) ;;
  *) die "Unknown command: $1 (use install, status, logs or stop)" ;;
esac

REF="$(envv AUTO_ONTOLOGY_REF)"; REF="${REF:-main}"
if [ ! -d auto-ontology/.git ]; then
  say "Downloading NVIDIA Auto Ontology"
  git clone --quiet https://github.com/NVIDIA/auto-ontology.git auto-ontology
fi
say "Using Auto Ontology version: $REF"
git -C auto-ontology fetch --quiet --tags origin
git -C auto-ontology checkout --quiet "$REF"
if git -C auto-ontology symbolic-ref -q HEAD >/dev/null; then
  git -C auto-ontology pull --quiet --ff-only
fi
say "Commit: $(git -C auto-ontology rev-parse --short HEAD)  (set AUTO_ONTOLOGY_REF to this to pin it)"

say "Building images (the first build takes several minutes)"
docker compose build
say "Starting"
docker compose up -d

say "Waiting for the web app"
for _ in $(seq 1 120); do
  if curl -fsS "http://127.0.0.1:3000/api/health" >/dev/null 2>&1; then
    APP_URL="$(envv APP_URL)"
    say "Auto Ontology is running at ${APP_URL}"
    cat <<EOF

Next steps
  1. Sign in at ${APP_URL} as $(envv AUTO_ONTOLOGY_ADMIN_EMAIL)
     (password: AUTO_ONTOLOGY_ADMIN_PASSWORD in .env).
  2. User menu > API Tokens > create a token.
  3. In ERPNext, Ontology Export Settings: paste it into API Token, Save,
     then click Check Setup and Push to Auto Ontology.
  Keep Settings > Semantic Compilation OFF for the first pilot.
EOF
    exit 0
  fi
  sleep 5
done
die "The web app did not come up in 10 minutes. Run: ./setup.sh logs"
